-- ----- source: ../src/database/migrations/060_add_receiving_status_to_po.sql -----

-- Add receiving_status column to track PO receiving status
-- open: when issued and/or GRN qty < PO qty
-- closed: when GRN qty = PO qty, or when PO is rejected
ALTER TABLE purchase_orders 
ADD COLUMN IF NOT EXISTS receiving_status VARCHAR(20) DEFAULT 'not_started';

-- Add index for faster filtering
CREATE INDEX IF NOT EXISTS idx_purchase_orders_receiving_status ON purchase_orders(receiving_status);

-- Note: We're keeping 'canceled' and 'closed' in the enum for backward compatibility
-- but the application will no longer use them. Instead:
-- - draft POs can be deleted
-- - rejected POs use 'rejected' status
-- - receiving status is tracked separately




-- ----- source: ../src/database/migrations/061_add_po_generation_flag_to_requisitions.sql -----

-- Add flag to track if a PR is closed for PO generation
-- This is a system-level flag that doesn't affect PR visibility
ALTER TABLE requisitions 
ADD COLUMN IF NOT EXISTS is_po_generated BOOLEAN DEFAULT FALSE;

-- Add index for faster filtering
CREATE INDEX IF NOT EXISTS idx_requisitions_po_generated ON requisitions(is_po_generated);

-- Update existing requisitions that have POs submitted
UPDATE requisitions r
SET is_po_generated = TRUE
WHERE EXISTS (
  SELECT 1 FROM purchase_orders po
  WHERE po.requisition_id = r.id
  AND po.status IN ('pending_approval', 'approved', 'issued')
);




